import fs from 'fs';
import path from 'path';

export interface Temple {
  id: string;
  name: string;
  deity: string;
  tradition: string;
  subType?: string;
  stoneType?: string;
  location?: string;
  country?: string;
  status: string;
  year?: string;
  height?: string;
  area?: string;
  coverImage?: string;
  images?: string[];
  description?: string;
  features?: string[];
  likes?: number;
  featured?: boolean;
  createdAt?: string;
}

export interface Contractor {
  name: string;
  title: string;
  experience: string;
  phone: string;
  whatsapp: string;
  email: string;
  headOffice: string;
  quarryYards: string;
  panIndiaCoverage: string;
  bio: string;
  specializations: string[];
  stats: {
    templesCompleted: string;
    statesCovered: string;
    artisansEmployed: string;
    heritageYears: string;
  };
}

export interface Enquiry {
  id: string;
  name: string;
  phone: string;
  email: string;
  deity?: string;
  tradition?: string;
  location?: string;
  budget?: string;
  message?: string;
  status?: string;
  createdAt?: string;
}

export interface DatabaseSchema {
  contractor: Contractor;
  temples: Temple[];
  enquiries: Enquiry[];
}

const DB_FILE = path.join(process.cwd(), 'data', 'temple_data.json');

export function readDb(): DatabaseSchema {
  try {
    if (!fs.existsSync(DB_FILE)) {
      const initial = require('../database.js');
      return initial.readDb();
    }
    const content = fs.readFileSync(DB_FILE, 'utf-8');
    return JSON.parse(content);
  } catch (err) {
    console.error("Database read error:", err);
    const initial = require('../database.js');
    return initial.readDb();
  }
}

export function writeDb(data: DatabaseSchema): boolean {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2), 'utf-8');
    return true;
  } catch (err) {
    console.error("Database write error:", err);
    return false;
  }
}
